let file = """{"version":3,"file":"partnerNodeGovernanceStore-o4VFW3F0.js","names":[],"sources":["../../src/platform/settings/composables/useSettingsHeaderCollapse.ts","../../src/platform/workspace/api/partnerNodePolicyApi.ts","../../src/platform/workspace/stores/partnerNodeGovernanceStore.ts"],"sourcesContent":["import { readonly, ref } from 'vue'\n\n/**\n * Collapses the workspace header in the settings dialog once a workspace panel\n * is scrolled, so the panel's controls can take the header's row alongside the\n * close button. Shared module state: the dialog is a singleton, and the panel\n * that owns the scroller is not the component that renders the header.\n */\nconst isHeaderCollapsed = ref(false)\n\n/**\n * Separate thresholds because collapsing feeds back into its own input:\n * lifting the controls row out of the panel body grows the scroller's viewport\n * and shrinks its overflow, which can clamp scrollTop back down. With a single\n * threshold that clamp re-expands the header, which restores the overflow, and\n * a marginally-scrollable panel flip-flops.\n */\nconst COLLAPSE_ABOVE_PX = 24\nconst EXPAND_BELOW_PX = 4\n\nexport function useSettingsHeaderCollapse() {\n  function handlePanelScroll(event: Event) {\n    const scroller = event.target\n    if (!(scroller instanceof HTMLElement)) return\n\n    const { scrollTop } = scroller\n    if (!isHeaderCollapsed.value && scrollTop > COLLAPSE_ABOVE_PX) {\n      isHeaderCollapsed.value = true\n    } else if (isHeaderCollapsed.value && scrollTop < EXPAND_BELOW_PX) {\n      isHeaderCollapsed.value = false\n    }\n  }\n\n  function resetHeaderCollapse() {\n    isHeaderCollapsed.value = false\n  }\n\n  return {\n    isHeaderCollapsed: readonly(isHeaderCollapsed),\n    handlePanelScroll,\n    resetHeaderCollapse\n  }\n}\n","import { z } from 'zod'\n\nimport { api } from '@/scripts/api'\n\nconst partnerProviderSchema = z.object({\n  provider_id: z.string(),\n  display_name: z.string(),\n  node_categories: z.array(z.string())\n})\n\nconst partnerProviderCatalogResponseSchema = z.object({\n  providers: z.array(partnerProviderSchema)\n})\n\nconst partnerProviderPolicyEntrySchema = z.object({\n  provider_id: z.string(),\n  enabled: z.boolean()\n})\n\nconst partnerNodePolicyResponseSchema = z.object({\n  enforcement_enabled: z.boolean(),\n  providers: z.array(partnerProviderPolicyEntrySchema)\n})\n\nexport interface PartnerProvider {\n  id: string\n  displayName: string\n  nodeCategories: readonly string[]\n}\n\nexport interface PartnerProviderPolicyEntry {\n  providerId: string\n  enabled: boolean\n}\n\nexport interface PartnerNodePolicy {\n  enforcementEnabled: boolean\n  providers: readonly PartnerProviderPolicyEntry[]\n}\n\nexport class PartnerNodePolicyApiError extends Error {\n  constructor(\n    public readonly status: number,\n    message: string\n  ) {\n    super(message)\n    this.name = 'PartnerNodePolicyApiError'\n  }\n}\n\nfunction normalizePolicy(\n  data: z.infer<typeof partnerNodePolicyResponseSchema>\n): PartnerNodePolicy {\n  return {\n    enforcementEnabled: data.enforcement_enabled,\n    providers: data.providers.map(({ provider_id, enabled }) => ({\n      providerId: provider_id,\n      enabled\n    }))\n  }\n}\n\nfunction throwResponseError(response: Response): never {\n  throw new PartnerNodePolicyApiError(response.status, response.statusText)\n}\n\nexport async function getPartnerProviders(): Promise<PartnerProvider[]> {\n  const response = await api.fetchApi('/providers', { cache: 'no-store' })\n  if (!response.ok) throwResponseError(response)\n\n  const data = partnerProviderCatalogResponseSchema.parse(await response.json())\n  return data.providers.map(\n    ({ provider_id, display_name, node_categories }) => ({\n      id: provider_id,\n      displayName: display_name,\n      nodeCategories: node_categories\n    })\n  )\n}\n\nexport async function getPartnerNodePolicy(): Promise<PartnerNodePolicy | null> {\n  const response = await api.fetchApi('/workspace/provider-policy', {\n    cache: 'no-store'\n  })\n  if (response.status === 404) return null\n  if (!response.ok) throwResponseError(response)\n\n  return normalizePolicy(\n    partnerNodePolicyResponseSchema.parse(await response.json())\n  )\n}\n\nexport async function updatePartnerNodePolicy(\n  policy: PartnerNodePolicy\n): Promise<PartnerNodePolicy> {\n  const response = await api.fetchApi('/workspace/provider-policy', {\n    method: 'PUT',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({\n      enforcement_enabled: policy.enforcementEnabled,\n      providers: policy.providers.map(({ providerId, enabled }) => ({\n        provider_id: providerId,\n        enabled\n      }))\n    })\n  })\n  if (!response.ok) throwResponseError(response)\n\n  return normalizePolicy(\n    partnerNodePolicyResponseSchema.parse(await response.json())\n  )\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, watch } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  getPartnerNodePolicy,\n  getPartnerProviders,\n  PartnerNodePolicyApiError,\n  updatePartnerNodePolicy\n} from '@/platform/workspace/api/partnerNodePolicyApi'\nimport type {\n  PartnerNodePolicy,\n  PartnerProvider\n} from '@/platform/workspace/api/partnerNodePolicyApi'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\n\nexport type PartnerNodePolicyStatus =\n  | 'inactive'\n  | 'loading'\n  | 'unconfigured'\n  | 'configured'\n  | 'ineligible'\n  | 'error'\n\nexport const usePartnerNodeGovernanceStore = defineStore(\n  'partnerNodeGovernance',\n  () => {\n    const { flags } = useFeatureFlags()\n    const workspaceStore = useTeamWorkspaceStore()\n\n    const providers = shallowRef<PartnerProvider[]>([])\n    const policy = shallowRef<PartnerNodePolicy | null>(null)\n    const status = ref<PartnerNodePolicyStatus>('inactive')\n    const error = shallowRef<Error | null>(null)\n    const activeSaveIdsByWorkspace = shallowRef(new Map<string, number>())\n    let requestVersion = 0\n    let nextSaveId = 0\n\n    const governedWorkspaceId = computed(() =>\n      flags.partnerNodeGovernanceEnabled\n        ? (workspaceStore.activeWorkspace?.id ?? null)\n        : null\n    )\n    const isSaving = computed(() => {\n      const workspaceId = governedWorkspaceId.value\n      return (\n        workspaceId !== null && activeSaveIdsByWorkspace.value.has(workspaceId)\n      )\n    })\n\n    function createInitialPolicy(): PartnerNodePolicy {\n      return {\n        enforcementEnabled: false,\n        providers: providers.value.map(({ id }) => ({\n          providerId: id,\n          enabled: true\n        }))\n      }\n    }\n\n    function isProviderEnabled(providerId: string): boolean {\n      if (!policy.value) return true\n      return (\n        policy.value.providers.find(\n          (provider) => provider.providerId === providerId\n        )?.enabled === true\n      )\n    }\n\n    async function loadPolicy(): Promise<void> {\n      const workspaceId = governedWorkspaceId.value\n      const version = ++requestVersion\n      if (!workspaceId) {\n        providers.value = []\n        policy.value = null\n        status.value = 'inactive'\n        error.value = null\n        return\n      }\n\n      providers.value = []\n      policy.value = null\n      status.value = 'loading'\n      error.value = null\n\n      const [providersResult, policyResult] = await Promise.allSettled([\n        getPartnerProviders(),\n        getPartnerNodePolicy()\n      ])\n      if (\n        version !== requestVersion ||\n        governedWorkspaceId.value !== workspaceId\n      ) {\n        return\n      }\n\n      const loadError =\n        policyResult.status === 'rejected'\n          ? policyResult.reason\n          : providersResult.status === 'rejected'\n            ? providersResult.reason\n            : null\n      if (loadError === null) {\n        const nextPolicy =\n          policyResult.status === 'fulfilled' ? policyResult.value : null\n        providers.value =\n          providersResult.status === 'fulfilled' ? providersResult.value : []\n        policy.value = nextPolicy\n        status.value = nextPolicy ? 'configured' : 'unconfigured'\n        return\n      }\n\n      // An ineligible workspace may still be allowed to read the catalog —\n      // keep it so the panel can render the gated view.\n      const ineligible =\n        loadError instanceof PartnerNodePolicyApiError &&\n        loadError.status === 403\n      providers.value =\n        ineligible && providersResult.status === 'fulfilled'\n          ? providersResult.value\n          : []\n      policy.value = null\n      error.value =\n        loadError instanceof Error\n          ? loadError\n          : new Error('Failed to load partner provider policy')\n      status.value = ineligible ? 'ineligible' : 'error'\n    }\n\n    async function savePolicy(nextPolicy: PartnerNodePolicy): Promise<void> {\n      const workspaceId = governedWorkspaceId.value\n      if (!workspaceId) return\n      if (activeSaveIdsByWorkspace.value.has(workspaceId)) {\n        console.error('Provider policy save already in progress')\n        return\n      }\n\n      const version = ++requestVersion\n      const saveId = ++nextSaveId\n      activeSaveIdsByWorkspace.value = new Map(\n        activeSaveIdsByWorkspace.value\n      ).set(workspaceId, saveId)\n      try {\n        const savedPolicy = await updatePartnerNodePolicy(nextPolicy)\n        if (\n          version !== requestVersion ||\n          governedWorkspaceId.value !== workspaceId\n        ) {\n          return\n        }\n\n        policy.value = savedPolicy\n        status.value = 'configured'\n        error.value = null\n      } catch (saveError) {\n        if (\n          version !== requestVersion ||\n          governedWorkspaceId.value !== workspaceId\n        ) {\n          return\n        }\n        if (\n          saveError instanceof PartnerNodePolicyApiError &&\n          saveError.status === 422\n        ) {\n          await loadPolicy()\n        }\n        throw saveError\n      } finally {\n        if (activeSaveIdsByWorkspace.value.get(workspaceId) === saveId) {\n          const nextActiveSaveIds = new Map(activeSaveIdsByWorkspace.value)\n          nextActiveSaveIds.delete(workspaceId)\n          activeSaveIdsByWorkspace.value = nextActiveSaveIds\n        }\n      }\n    }\n\n    async function setProviderEnabled(\n      providerId: string,\n      enabled: boolean\n    ): Promise<void> {\n      if (!providers.value.some(({ id }) => id === providerId)) return\n\n      const currentPolicy = policy.value ?? createInitialPolicy()\n      const currentEntry = currentPolicy.providers.find(\n        (provider) => provider.providerId === providerId\n      )\n      const nextProviders = currentEntry\n        ? currentPolicy.providers.map((provider) =>\n            provider.providerId === providerId\n              ? { ...provider, enabled }\n              : provider\n          )\n        : [...currentPolicy.providers, { providerId, enabled }]\n\n      await savePolicy({\n        ...currentPolicy,\n        enforcementEnabled: currentPolicy.enforcementEnabled || !enabled,\n        providers: nextProviders\n      })\n    }\n\n    async function setProvidersEnabled(\n      providerIds: string[],\n      enabled: boolean\n    ): Promise<void> {\n      const targetIds = new Set(providerIds)\n      if (!providers.value.some(({ id }) => targetIds.has(id))) return\n\n      const currentPolicy = policy.value ?? createInitialPolicy()\n      await savePolicy({\n        ...currentPolicy,\n        enforcementEnabled: currentPolicy.enforcementEnabled || !enabled,\n        providers: providers.value.map(({ id }) =>\n          targetIds.has(id)\n            ? { providerId: id, enabled }\n            : (currentPolicy.providers.find(\n                ({ providerId }) => providerId === id\n              ) ?? { providerId: id, enabled: false })\n        )\n      })\n    }\n\n    async function setAllProvidersEnabled(enabled: boolean): Promise<void> {\n      const currentPolicy = policy.value ?? createInitialPolicy()\n      await savePolicy({\n        ...currentPolicy,\n        enforcementEnabled: currentPolicy.enforcementEnabled || !enabled,\n        providers: providers.value.map(({ id }) => ({\n          providerId: id,\n          enabled\n        }))\n      })\n    }\n\n    async function setEnforcementEnabled(enabled: boolean): Promise<void> {\n      const currentPolicy = policy.value ?? createInitialPolicy()\n      await savePolicy({\n        ...currentPolicy,\n        enforcementEnabled: enabled\n      })\n    }\n\n    watch(governedWorkspaceId, () => void loadPolicy(), { immediate: true })\n\n    return {\n      providers,\n      policy,\n      status,\n      error,\n      isSaving,\n      governedWorkspaceId,\n      isProviderEnabled,\n      loadPolicy,\n      setProviderEnabled,\n      setProvidersEnabled,\n      setAllProvidersEnabled,\n      setEnforcementEnabled\n    }\n  }\n)\n"],"mappings":"4UAQA,IAAM,EAAoB,EAAI,EAAK,EAS7B,EAAoB,GACpB,EAAkB,EAExB,SAAgB,2BAA4B,CAC1C,SAAS,kBAAkB,EAAc,CACvC,IAAM,EAAW,EAAM,OACvB,GAAI,EAAE,aAAoB,aAAc,OAExC,GAAM,CAAE,aAAc,EAClB,CAAC,EAAkB,OAAS,EAAY,EAC1C,EAAkB,MAAQ,GACjB,EAAkB,OAAS,EAAY,IAChD,EAAkB,MAAQ,GAE9B,CAEA,SAAS,qBAAsB,CAC7B,EAAkB,MAAQ,EAC5B,CAEA,MAAO,CACL,kBAAmB,EAAS,CAAiB,EAC7C,kBACA,mBACF,CACF,CCtCA,IAAM,EAAwB,EAAS,CACrC,YAAa,EAAS,EACtB,aAAc,EAAS,EACvB,gBAAiB,EAAQ,EAAS,CAAC,CACrC,CAAC,EAEK,EAAuC,EAAS,CACpD,UAAW,EAAQ,CAAqB,CAC1C,CAAC,EAEK,EAAmC,EAAS,CAChD,YAAa,EAAS,EACtB,QAAS,EAAU,CACrB,CAAC,EAEK,EAAkC,EAAS,CAC/C,oBAAqB,EAAU,EAC/B,UAAW,EAAQ,CAAgC,CACrD,CAAC,EAkBY,0BAAb,cAA+C,KAAM,CAEjC,OADlB,YACE,EACA,EACA,CACA,MAAM,CAAO,EAHG,KAAA,OAAA,EAIhB,KAAK,KAAO,2BACd,CACF,EAEA,SAAS,gBACP,EACmB,CACnB,MAAO,CACL,mBAAoB,EAAK,oBACzB,UAAW,EAAK,UAAU,KAAK,CAAE,cAAa,cAAe,CAC3D,WAAY,EACZ,SACF,EAAE,CACJ,CACF,CAEA,SAAS,mBAAmB,EAA2B